CREATE TABLE trade_in_devices (id BIGINT AUTO_INCREMENT PRIMARY KEY, model VARCHAR(100) NOT NULL UNIQUE, base_price DECIMAL(15,0) NOT NULL, subsidy_amount DECIMAL(15,0) NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(base_price>=0 AND subsidy_amount>=0));
CREATE TABLE trade_in_criterias (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, deduction_percent INT NOT NULL, CHECK(deduction_percent BETWEEN 0 AND 100));
CREATE TABLE trade_in_requests (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, device_id BIGINT NOT NULL, criteria_id BIGINT NOT NULL, old_imei VARCHAR(40) NOT NULL UNIQUE, quoted_amount DECIMAL(15,0) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'QUOTED', order_id BIGINT NULL UNIQUE, created_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(device_id) REFERENCES trade_in_devices(id), FOREIGN KEY(criteria_id) REFERENCES trade_in_criterias(id));
CREATE TABLE installment_plans (id BIGINT AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(100) NOT NULL, months INT NOT NULL, fee_percent DECIMAL(5,2) NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(months IN(3,6,9,12) AND fee_percent>=0));
CREATE TABLE installment_applications (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, plan_id BIGINT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', financed_amount DECIMAL(15,0) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(plan_id) REFERENCES installment_plans(id));
